'use client';

import { useState, useEffect, useCallback } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { motion, AnimatePresence } from 'framer-motion';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { 
  Clock, 
  Gavel, 
  TrendingUp, 
  Users, 
  Eye,
  ArrowLeft,
  Share2,
  Bell,
  Calendar,
  MapPin,
  Trophy,
  History,
  Shield,
  Loader2,
  CheckCircle,
  AlertCircle,
  Zap,
  Timer,
  Sparkles
} from 'lucide-react';
import { BidForm } from '@/components/auction/BidForm';
import { apiClient } from '@/lib/api/client';
import { toast } from '@/hooks/use-toast';
import { useTheme } from '@/lib/context/ThemeContext';
import Link from 'next/link';
import { PublicHeader } from '@/components/shared/public-header';
import { Footer } from '@/components/shared/footer';

export default function AuctionDetailPage() {
  const params = useParams();
  const router = useRouter();
  const { theme } = useTheme();
  const isDark = theme === 'dark';
  const auctionId = params.auctionId as string;

  const [auction, setAuction] = useState<any>(null);
  const [bids, setBids] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [timeRemaining, setTimeRemaining] = useState(0);

  const fetchAuction = useCallback(async () => {
    try {
      const data = await apiClient.getAuction(auctionId);

      if (data.success) {
        setAuction(data.auction);
        setBids(data.bids);
        setTimeRemaining(data.auction.timeRemainingMs);
      } else {
        setError(data.error || 'Failed to load auction');
      }
    } catch (err: any) {
      setError(err.message || 'Failed to load auction');
    } finally {
      setLoading(false);
    }
  }, [auctionId]);

  useEffect(() => {
    fetchAuction();
    
    // Poll for updates every 10 seconds
    const pollInterval = setInterval(fetchAuction, 10000);
    
    return () => clearInterval(pollInterval);
  }, [fetchAuction]);

  // Live countdown
  useEffect(() => {
    if (timeRemaining <= 0) return;

    const interval = setInterval(() => {
      setTimeRemaining(prev => Math.max(0, prev - 1000));
    }, 1000);

    return () => clearInterval(interval);
  }, [timeRemaining]);

  const formatTime = (ms: number): { days: number; hours: number; minutes: number; seconds: number } => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);
    
    return {
      days,
      hours: hours % 24,
      minutes: minutes % 60,
      seconds: seconds % 60,
    };
  };

  const handleBidPlaced = (bid: { amountEth: number }) => {
    // Refresh auction data
    fetchAuction();
  };

  const handleShare = async () => {
    const url = window.location.href;
    if (navigator.share) {
      await navigator.share({
        title: `Auction: ${auction?.eventId?.title}`,
        text: `Check out this ticket auction!`,
        url,
      });
    } else {
      await navigator.clipboard.writeText(url);
      toast({
        title: 'Link Copied!',
        description: 'Auction link copied to clipboard',
      });
    }
  };

  if (loading) {
    return (
      <div className={`min-h-screen ${isDark ? 'bg-[#0A0A0A]' : 'bg-gray-50'}`}>
        <PublicHeader />
        <div className="flex flex-col items-center justify-center min-h-[60vh] pt-20">
          <div className="relative">
            <div className="w-20 h-20 rounded-full border-4 border-orange-500/20 border-t-orange-500 animate-spin" />
            <Gavel className="h-8 w-8 text-orange-400 absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2" />
          </div>
          <p className={`mt-6 text-lg ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>Loading auction...</p>
        </div>
        <Footer />
      </div>
    );
  }

  if (error || !auction) {
    return (
      <div className={`min-h-screen ${isDark ? 'bg-[#0A0A0A]' : 'bg-gray-50'}`}>
        <PublicHeader />
        <div className="flex flex-col items-center justify-center min-h-[60vh] pt-20 gap-4">
          <div className="w-20 h-20 rounded-full bg-red-500/20 flex items-center justify-center">
            <AlertCircle className="h-10 w-10 text-red-400" />
          </div>
          <h2 className={`text-xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
            Oops! Something went wrong
          </h2>
          <p className={isDark ? 'text-gray-400' : 'text-gray-600'}>{error || 'Auction not found'}</p>
          <Button 
            onClick={() => router.back()}
            className="bg-gradient-to-r from-orange-500 to-amber-500 hover:from-orange-600 hover:to-amber-600 text-white border-0"
          >
            <ArrowLeft className="h-4 w-4 mr-2" />
            Go Back
          </Button>
        </div>
        <Footer />
      </div>
    );
  }

  const time = formatTime(timeRemaining);
  const isEnded = timeRemaining <= 0 || auction.status !== 'active';
  const isEndingSoon = timeRemaining > 0 && timeRemaining < 30 * 60 * 1000;

  const eventImage = auction.eventId?.image || auction.eventId?.imageUrl || '/placeholder-event.jpg';

  return (
    <div className={`min-h-screen ${isDark ? 'bg-[#0A0A0A]' : 'bg-gray-50'}`}>
      {/* Header */}
      <PublicHeader />

      {/* Breadcrumb & Actions */}
      <div className={`sticky top-20 z-10 ${isDark ? 'bg-[#0A0A0A]/95 border-white/10' : 'bg-white/95 border-gray-200'} border-b backdrop-blur-xl`}>
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => router.back()}
              className={isDark ? 'text-gray-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}
            >
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back
            </Button>
            <span className={`text-sm ${isDark ? 'text-gray-600' : 'text-gray-400'}`}>/</span>
            <Link href="/auction" className={`text-sm ${isDark ? 'text-gray-400 hover:text-white' : 'text-gray-600 hover:text-gray-900'}`}>
              Auctions
            </Link>
            <span className={`text-sm ${isDark ? 'text-gray-600' : 'text-gray-400'}`}>/</span>
            <span className={`text-sm ${isDark ? 'text-orange-400' : 'text-orange-600'}`}>
              {auction.ticketTypeId?.name || 'Ticket'}
            </span>
          </div>
          
          <div className="flex items-center gap-2">
            <Button 
              variant="outline" 
              size="sm" 
              onClick={handleShare}
              className={isDark ? 'border-white/20 hover:bg-white/10' : ''}
            >
              <Share2 className="h-4 w-4 mr-2" />
              Share
            </Button>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Event Image & Info */}
            <Card className={isDark ? 'bg-gray-800/50 border-gray-700 overflow-hidden' : 'bg-white border-gray-200 overflow-hidden'}>
              <div className="relative h-64 md:h-80">
                <img
                  src={eventImage}
                  alt={auction.eventId?.title}
                  className="w-full h-full object-cover transition-transform duration-500 hover:scale-105"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />
                
                {/* Status Badge */}
                <div className="absolute top-4 left-4">
                  {isEnded ? (
                    <Badge className="bg-gray-500 text-white">Ended</Badge>
                  ) : isEndingSoon ? (
                    <Badge className="bg-red-500 text-white animate-pulse">
                      <Clock className="h-3 w-3 mr-1" />
                      Ending Soon
                    </Badge>
                  ) : (
                    <Badge className="bg-green-500 text-white">Live</Badge>
                  )}
                </div>

                {/* Event Info Overlay */}
                <div className="absolute bottom-4 left-4 right-4">
                  <Badge variant="secondary" className="mb-2">
                    {auction.ticketTypeId?.name}
                  </Badge>
                  <h1 className="text-2xl md:text-3xl font-bold text-white mb-2">
                    {auction.eventId?.title}
                  </h1>
                  <div className="flex flex-wrap gap-4 text-white/80 text-sm">
                    <span className="flex items-center gap-1">
                      <Calendar className="h-4 w-4" />
                      {new Date(auction.eventId?.date).toLocaleDateString('en-IN', {
                        day: 'numeric',
                        month: 'long',
                        year: 'numeric'
                      })}
                    </span>
                    <span className="flex items-center gap-1">
                      <MapPin className="h-4 w-4" />
                      {auction.eventId?.venue}
                    </span>
                  </div>
                </div>
              </div>
            </Card>

            {/* Countdown Timer */}
            {!isEnded && (
              <Card className={`${isEndingSoon ? 'ring-2 ring-red-500' : ''} ${isDark ? 'bg-gray-800/50 border-gray-700' : 'bg-white border-gray-200'}`}>
                <CardContent className="py-6">
                  <div className="text-center">
                    <p className={`text-sm mb-3 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                      Auction ends in
                    </p>
                    <div className="flex justify-center gap-4">
                      {[
                        { value: time.days, label: 'Days' },
                        { value: time.hours, label: 'Hours' },
                        { value: time.minutes, label: 'Min' },
                        { value: time.seconds, label: 'Sec' },
                      ].map((item, i) => (
                        <div key={i} className="text-center">
                          <div className={`text-3xl md:text-4xl font-mono font-bold ${
                            isEndingSoon ? 'text-red-500' : isDark ? 'text-white' : 'text-gray-900'
                          }`}>
                            {String(item.value).padStart(2, '0')}
                          </div>
                          <div className={`text-xs ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>
                            {item.label}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </CardContent>
              </Card>
            )}

            {/* Bid History */}
            <Card className={isDark ? 'bg-gray-800/50 border-gray-700' : 'bg-white border-gray-200'}>
              <CardHeader>
                <CardTitle className={`flex items-center gap-2 ${isDark ? 'text-white' : 'text-gray-900'}`}>
                  <History className="h-5 w-5 text-orange-500" />
                  Bid History
                </CardTitle>
              </CardHeader>
              <CardContent>
                {bids.length === 0 ? (
                  <div className={`text-center py-8 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    <Gavel className="h-12 w-12 mx-auto mb-3 opacity-50" />
                    <p>No bids yet. Be the first!</p>
                  </div>
                ) : (
                  <div className="space-y-3">
                    {bids.map((bid, index) => (
                      <motion.div
                        key={bid.id}
                        initial={{ opacity: 0, x: -20 }}
                        animate={{ opacity: 1, x: 0 }}
                        transition={{ delay: index * 0.05 }}
                        className={`flex items-center justify-between p-3 rounded-lg ${
                          index === 0 
                            ? isDark ? 'bg-orange-500/20 border border-orange-500/30' : 'bg-orange-50 border border-orange-200'
                            : isDark ? 'bg-gray-700/50' : 'bg-gray-100'
                        }`}
                      >
                        <div className="flex items-center gap-3">
                          {index === 0 && <Trophy className="h-5 w-5 text-orange-500" />}
                          <div>
                            <p className={`font-medium ${isDark ? 'text-white' : 'text-gray-900'}`}>
                              {bid.bidderName}
                            </p>
                            <p className={`text-xs ${isDark ? 'text-gray-400' : 'text-gray-500'}`}>
                              {new Date(bid.placedAt).toLocaleString()}
                            </p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className={`font-bold ${index === 0 ? 'text-orange-500' : isDark ? 'text-white' : 'text-gray-900'}`}>
                            {bid.amountEth.toFixed(4)} ETH
                          </p>
                          {bid.causedExtension && (
                            <Badge variant="outline" className="text-xs">
                              +10 min
                            </Badge>
                          )}
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Current Bid Card */}
            <Card className={`${isDark ? 'bg-white/5 border-white/10' : 'bg-white border-gray-200'} shadow-xl`}>
              <CardContent className="py-6">
                <div className="text-center mb-4">
                  <p className={`text-sm ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                    {auction.currentBidEth > 0 ? 'Current Bid' : 'Starting Bid'}
                  </p>
                  <div className="flex items-center justify-center gap-2 mt-1">
                    <TrendingUp className="h-6 w-6 text-green-500" />
                    <span className={`text-3xl font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {auction.currentBidEth > 0 
                        ? auction.currentBidEth.toFixed(4) 
                        : auction.startingBidEth.toFixed(4)
                      } ETH
                    </span>
                  </div>
                </div>

                <Separator className={isDark ? 'bg-gray-700' : 'bg-gray-200'} />

                <div className="grid grid-cols-3 gap-4 mt-4 text-center">
                  <div>
                    <Gavel className={`h-5 w-5 mx-auto mb-1 ${isDark ? 'text-gray-400' : 'text-gray-500'}`} />
                    <p className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {auction.totalBids}
                    </p>
                    <p className={`text-xs ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>Bids</p>
                  </div>
                  <div>
                    <Users className={`h-5 w-5 mx-auto mb-1 ${isDark ? 'text-gray-400' : 'text-gray-500'}`} />
                    <p className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {auction.uniqueBidders}
                    </p>
                    <p className={`text-xs ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>Bidders</p>
                  </div>
                  <div>
                    <Eye className={`h-5 w-5 mx-auto mb-1 ${isDark ? 'text-gray-400' : 'text-gray-500'}`} />
                    <p className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                      {auction.views}
                    </p>
                    <p className={`text-xs ${isDark ? 'text-gray-500' : 'text-gray-500'}`}>Views</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Bid Form or Result */}
            {!isEnded ? (
              <BidForm
                auctionId={auctionId}
                currentBidEth={auction.currentBidEth}
                minNextBidEth={auction.minNextBidEth}
                maxAllowedBidEth={auction.maxAllowedBidEth}
                bidIncrementEth={auction.bidIncrementEth}
                onBidPlaced={handleBidPlaced}
              />
            ) : (
              <Card className={isDark ? 'bg-gray-800/50 border-gray-700' : 'bg-white border-gray-200'}>
                <CardContent className="py-6 text-center">
                  {auction.status === 'settled' && auction.winnerId ? (
                    <>
                      <Trophy className="h-12 w-12 text-yellow-500 mx-auto mb-3" />
                      <h3 className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                        Auction Completed
                      </h3>
                      <p className={`mt-2 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                        Sold for {auction.finalPriceEth?.toFixed(4)} ETH
                      </p>
                    </>
                  ) : (
                    <>
                      <AlertCircle className="h-12 w-12 text-gray-400 mx-auto mb-3" />
                      <h3 className={`text-lg font-bold ${isDark ? 'text-white' : 'text-gray-900'}`}>
                        Auction Ended
                      </h3>
                      <p className={`mt-2 ${isDark ? 'text-gray-400' : 'text-gray-600'}`}>
                        {auction.status === 'no_bids' ? 'No bids received' : 
                         auction.status === 'reserve_not_met' ? 'Reserve price not met' :
                         'This auction has ended'}
                      </p>
                    </>
                  )}
                </CardContent>
              </Card>
            )}

            {/* Auction Info */}
            <Card className={`${isDark ? 'bg-white/5 border-white/10' : 'bg-white border-gray-200'} shadow-lg`}>
              <CardHeader className="pb-3">
                <CardTitle className={`text-sm ${isDark ? 'text-gray-300' : 'text-gray-700'}`}>
                  Auction Details
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3 text-sm">
                <div className="flex justify-between">
                  <span className={isDark ? 'text-gray-400' : 'text-gray-600'}>Starting Bid</span>
                  <span className={isDark ? 'text-white' : 'text-gray-900'}>
                    {auction.startingBidEth.toFixed(4)} ETH
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className={isDark ? 'text-gray-400' : 'text-gray-600'}>Bid Increment</span>
                  <span className={isDark ? 'text-white' : 'text-gray-900'}>
                    {auction.bidIncrementEth.toFixed(4)} ETH
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className={isDark ? 'text-gray-400' : 'text-gray-600'}>Price Cap</span>
                  <span className={isDark ? 'text-white' : 'text-gray-900'}>
                    {auction.maxAllowedBidEth?.toFixed(4)} ETH
                  </span>
                </div>
                <Separator className={isDark ? 'bg-gray-700' : 'bg-gray-200'} />
                <div className="flex items-center gap-2 text-xs">
                  <Shield className="h-4 w-4 text-green-500" />
                  <span className={isDark ? 'text-gray-400' : 'text-gray-600'}>
                    Anti-sniping: +10 min on late bids
                  </span>
                </div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
}
